      "translation": "preporučiti se • biti preporučljiv",
      "explanation": [
        "Glavna ideja: sich empfehlen u ovom značenju koristi se gotovo samo u 3. licu, s es ili s imenicom: es empfiehlt sich, … — preporučljivo je, poželjno je nešto uraditi. Ono što se tako opisuje je preporučljivo, samo se preporučuje.",
        "Oblici: empfiehlt sich, empfahl sich, hat sich empfohlen (e prelazi u ie). Nakon njega često dolazi zu + infinitiv ili rečenica s dass: Es empfiehlt sich, früh zu buchen.",
        "U drugom, formalnom značenju sich empfehlen znači i oprostiti se, otići: Er empfahl sich früh."
      ],
      "examples": [
        {
          "de": "Es empfiehlt sich, früh zu buchen.",
          "lv": "Preporučljivo je rezervisati na vrijeme."
        },
        {
          "de": "Bei Regen empfiehlt sich eine Jacke.",
          "lv": "Po kiši se preporučuje jakna."
        },
        {
          "de": "Es empfiehlt sich, die Datei vorher zu speichern.",
          "lv": "Preporučljivo je prethodno sačuvati datoteku."
        },
        {
          "de": "Vor der Reise empfiehlt sich eine Impfung.",
          "lv": "Prije putovanja preporučuje se vakcinacija."
        }
      ],
      "comparison": [
        {
          "word": "empfehlen",
          "meaning": "preporučiti",
          "example": "Ich empfehle dir dieses Restaurant. – Preporučujem ti ovaj restoran."
        },
        {
          "word": "ratsam",
          "meaning": "preporučljiv",
          "example": "Es ist ratsam, einen Schirm mitzunehmen. – Preporučljivo je ponijeti kišobran."
        },
        {
          "word": "sich verabschieden",
          "meaning": "oprostiti se",
          "example": "Wir verabschieden uns jetzt. – Sada se opraštamo."
        }
      ],
      "tip": [
        "Shema rečenice: Es empfiehlt sich + zu + infinitiv — zgodno kad ne želiš reći ko preporučuje.",
        "Sinonim jednostavnije građe: Es ist ratsam."
      ],
      "important": [
        "Ovo značenje gotovo je uvijek u 3. licu (empfiehlt sich); oblici s ich ili du ovdje ne odgovaraju.",
        "Ne miješaj s empfehlen (nekome nešto preporučiti): Ich empfehle dir das Buch."
      ],
