      "layout": "standardStudy",
      "translation": "stidjeti se • sramiti se",
      "explanation": [
        "Glavna ideja: sich genieren znači stidjeti se, osjećati se nelagodno kad nešto treba uraditi pred drugima. U izgovoru se g čita kao ž: [ʒeˈniːrən].",
        "Osobe pred kojima se neko stidi izražavaju se s vor + dativ: sich vor den Gästen genieren. Oblici: geniert sich, genierte sich, hat sich geniert. Često se koristi u negaciji: Genieren Sie sich nicht! — Nemojte se ustručavati!"
      ],
      "examples": [
        {
          "de": "Er geniert sich vor fremden Leuten.",
          "lv": "Stidi se pred nepoznatim ljudima."
        },
        {
          "de": "Du brauchst dich nicht zu genieren.",
          "lv": "Ne moraš se stidjeti."
        },
        {
          "de": "Sie genierte sich, nach dem Weg zu fragen.",
          "lv": "Bilo ju je sramota pitati za put."
        },
        {
          "de": "Bitte genieren Sie sich nicht, greifen Sie zu!",
          "lv": "Molim vas, ne ustručavajte se, poslužite se!"
        }
      ],
      "comparison": [
        {
          "word": "sich schämen",
          "meaning": "stidjeti se",
          "example": "Ich schäme mich für meinen Fehler. – Stidim se svoje greške."
        },
        {
          "word": "schüchtern",
          "meaning": "stidljiv",
          "example": "Er ist sehr schüchtern. – Veoma je stidljiv."
        },
        {
          "word": "peinlich",
          "meaning": "neugodan",
          "example": "Das ist mir peinlich. – To mi je neugodno."
        }
      ],
      "tip": [
        "Gostoljubiv poziv: Genieren Sie sich nicht!",
        "U neugodnoj situaciji reci i Das ist mir unangenehm."
      ],
      "important": [
        "sich genieren izražava društvenu stidljivost, a sich schämen stid zbog vlastitog postupka.",
        "Riječ je preuzeta iz francuskog, pa je izgovor sa ž važan."
      ],
