      "explanation": [
        "Glavna ideja: das Hochwasser je imenica srednjeg roda. Znači veoma visok vodostaj rijeke, mora ili jezera i poplavu koju on izaziva. Množina je die Hochwasser (i Hochwässer).",
        "Česti izrazi: Hochwasser führen (rijeka ima visok vodostaj), vor Hochwasser warnen (upozoravati na poplave), vom Hochwasser betroffen sein (biti pogođen poplavom). Suprotnost je das Niedrigwasser."
      ],
      "examples": [
        {
          "de": "Nach dem Regen gibt es Hochwasser.",
          "lv": "Nakon kiše dolazi do poplava."
        },
        {
          "de": "Der Fluss führt Hochwasser.",
          "lv": "Rijeka ima visok vodostaj."
        },
        {
          "de": "Die Behörden warnen vor Hochwasser.",
          "lv": "Nadležni organi upozoravaju na poplave."
        },
        {
          "de": "Das Hochwasser hat mehrere Dörfer erreicht.",
          "lv": "Poplava je dosegla nekoliko sela."
        }
      ],
      "comparison": [
        {
          "word": "die Überschwemmung",
          "meaning": "poplava, plavljenje",
          "example": "Die Überschwemmung zerstörte die Ernte. – Poplava je uništila usjeve."
        },
        {
          "word": "die Flut",
          "meaning": "plima",
          "example": "Die Flut kommt am Abend. – Plima dolazi uvečer."
        },
        {
          "word": "das Niedrigwasser",
          "meaning": "nizak vodostaj",
          "example": "Bei Niedrigwasser fahren weniger Schiffe. – Pri niskom vodostaju plovi manje brodova."
        }
      ],
      "tip": [
        "Zapamti suprotnost: Hochwasser — Niedrigwasser.",
        "U vijestima ćeš često čuti Hochwasserwarnung, Hochwasserschutz."
      ],
      "important": [
        "Hochwasser nije isto što i Flut (morska plima).",
        "U množini je član die, a riječ ostaje nepromijenjena: die Hochwasser."
      ],
