        "Oblici: wechselt, wechselte, hat gewechselt. Prelazni glagol traži akuzativ: etwas wechseln. Za promjenu pravca ili mjesta koriste se prijedlozi in/auf/zu: Er wechselt zu einem anderen Verein.",
